-- R3 Authorization Engine Unification.
-- Human Admin HTTP APIs use only Canonical IAM Atomic Permissions and Role Bindings.

select set_config('app.current_tenant_id','INSTANCE',true);
select set_config('app.current_actor_id','r3-authorization-unification',true);

select '00000000-0000-0000-0000-000000000011'::uuid,'R3-AUTHORIZATION-0.8.2',coalesce(max(revision_number),0)+1,'DRAFT','DRAFT:UNPUBLISHED','R3 single Human Admin Authorization Engine and target-only route catalog.',(select revision_id from permission_catalog_active_revision where singleton_id='ACTIVE'),now(),'r3-authorization-unification',null,null,1 from permission_catalog_revisions on conflict(revision_id) do nothing;

select '00000000-0000-0000-0000-000000000011'::uuid,e.permission_code,e.owner_module,e.resource_type,e.action_code,e.description,e.risk_level,e.risk_lane,e.lifecycle,e.allowed_scope_types,e.system_managed,e.replacement_permission_code,e.introduced_at,e.deprecated_at,e.retired_at,now(),'r3-authorization-unification',1 from permission_catalog_revision_entries e join permission_catalog_active_revision a on a.singleton_id='ACTIVE' and a.revision_id=e.revision_id on conflict(revision_id,permission_code) do nothing;
