select 'r3-'||substr(md5(b.binding_id||':'||target.role_id),1,40),b.tenant_id,b.principal_type,b.principal_id,target.role_id,b.scope_type,b.scope_id,b.effective_at,b.expires_at,'ACTIVE',now(),'r3-authorization-unification',1 from rbac_principal_role_bindings b join rbac_roles legacy on legacy.role_id=b.role_id join rbac_roles target on target.role_code=case legacy.role_code when 'LEGACY_ADMIN' then 'TENANT_ADMIN' when 'LEGACY_OPERATOR' then 'OPERATOR' when 'LEGACY_VIEWER' then 'VIEWER' end and target.tenant_id is null where legacy.role_code in('LEGACY_ADMIN','LEGACY_OPERATOR','LEGACY_VIEWER') and b.status='ACTIVE' on conflict(binding_id) do nothing;
update rbac_principal_role_bindings b set status='REVOKED',revoked_at=now(),revoked_by='r3-authorization-unification',revoke_reason='Replaced by canonical R3 Role Binding',version=b.version+1 from rbac_roles r where r.role_id=b.role_id and r.role_code in('LEGACY_ADMIN','LEGACY_OPERATOR','LEGACY_VIEWER') and b.status='ACTIVE';
update rbac_roles set status='DISABLED',updated_at=now(),updated_by='r3-authorization-unification',version=version+1 where role_code in('LEGACY_ADMIN','LEGACY_OPERATOR','LEGACY_VIEWER') and status='ACTIVE';

update permission_entry_point_bypasses set status='REVOKED',revoked_at=now(),revoked_by='r3-authorization-unification',revoke_reason='R3 target-only cutover removed the compatibility bypass',version=version+1 where status='ACTIVE' and entry_point_id in (select entry_point_id from permission_entry_point_inventory where entry_point_type in('REST','EXPORT') and route_pattern is not null and route_pattern not like '/internal/%' and route_pattern not like '/api/events/%' and route_pattern not like '/api/external/provider-webhooks/%');
update permission_legacy_authority_mappings set status='RETIRED',migration_deadline=null,notes=case when notes='' then 'Retired by R3 target-only Authorization Engine cutover' else notes||' | Retired by R3 target-only Authorization Engine cutover' end,updated_at=now(),updated_by='r3-authorization-unification',version=version+1 where status<>'RETIRED';

update permission_entry_point_inventory set authority_state='EXEMPT',target_permission_code=null,legacy_authority_type=null,legacy_authorities='[]'::jsonb,exemption_reason='Retired or no longer active in the R3 Human Admin controller inventory',migration_deadline=null,manifest_revision='r3-target-only-2026-08-03',last_verified_at=now(),updated_at=now(),updated_by='r3-authorization-unification',version=version+1 where entry_point_type in('REST','EXPORT') and route_pattern is not null and route_pattern not like '/internal/%' and route_pattern not like '/api/events/%' and route_pattern not like '/api/external/provider-webhooks/%';

on conflict(entry_point_id) do update set entry_point_type=excluded.entry_point_type,application_id=excluded.application_id,owner_module=excluded.owner_module,display_name=excluded.display_name,route_pattern=excluded.route_pattern,http_method=excluded.http_method,authority_state=excluded.authority_state,target_permission_code=excluded.target_permission_code,legacy_authority_type=null,legacy_authorities='[]'::jsonb,resource_type=excluded.resource_type,resource_resolver_id=excluded.resource_resolver_id,exemption_reason=excluded.exemption_reason,migration_deadline=null,manifest_revision=excluded.manifest_revision,source_ref=excluded.source_ref,source_hash=excluded.source_hash,last_verified_at=now(),updated_at=now(),updated_by='r3-authorization-unification',version=permission_entry_point_inventory.version+1;

do $$ begin if exists(select 1 from permission_entry_point_inventory where entry_point_type in('REST','EXPORT') and route_pattern is not null and route_pattern not like '/internal/%' and route_pattern not like '/api/events/%' and route_pattern not like '/api/external/provider-webhooks/%' and authority_state in('LEGACY_ONLY','DUAL_SHADOW','TARGET_READY')) then raise exception 'R3 target-only cutover left a non-target Human HTTP authority state'; end if; if exists(select 1 from permission_entry_point_inventory where authority_state='TARGET_ONLY' and (target_permission_code is null or resource_resolver_id is null)) then raise exception 'R3 target-only cutover left an unmapped permission or resource resolver'; end if; end $$;

update rbac_policy_versions set policy_version=policy_version+1,updated_at=now(),updated_by='r3-authorization-unification';
